CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY, issuer text NOT NULL, subject text NOT NULL, disabled boolean NOT NULL DEFAULT false, admin boolean NOT NULL DEFAULT false, UNIQUE(issuer,subject));
CREATE TABLE IF NOT EXISTS sessions (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, csrf text NOT NULL, expires timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS oauth_flows (id text PRIMARY KEY, browser text NOT NULL, user_id text REFERENCES users(id) ON DELETE CASCADE, provider text NOT NULL, purpose text NOT NULL, verifier text NOT NULL, nonce text NOT NULL, expires timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS accounts (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), provider text NOT NULL CHECK(provider IN ('google','microsoft')), issuer text NOT NULL, subject text NOT NULL, token text, status text NOT NULL, UNIQUE(provider,issuer,subject));
CREATE TABLE IF NOT EXISTS pairs (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), google_id text NOT NULL UNIQUE REFERENCES accounts(id), microsoft_id text NOT NULL UNIQUE REFERENCES accounts(id), folder text NOT NULL, enabled boolean NOT NULL DEFAULT false, deletion boolean NOT NULL DEFAULT false, interval integer NOT NULL DEFAULT 300 CHECK(interval>=60), next_run timestamptz NOT NULL DEFAULT now(), revision integer NOT NULL DEFAULT 0, state jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS jobs (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), pair_id text REFERENCES pairs(id) ON DELETE CASCADE, status text NOT NULL, counts jsonb NOT NULL DEFAULT '{}', code text, created timestamptz NOT NULL DEFAULT now(), finished timestamptz);
CREATE INDEX IF NOT EXISTS jobs_owner ON jobs(user_id,created DESC);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires);
